#!/usr/bin/env node
// Build the agent30-cadcode-v3 dataset: the same 30 EVAL_ONLY targets as agent30-cadcode-v2, with
//   * target.ir.jsonl regenerated by STEPIR v6.3 (the simplecadapi skill's scripts/stepir.py bundled with CAD Code, on
//     SimpleCADAPI 2.2.7): spline loop segments written exactly, straight-extruded spline walls as EXT, loop prisms
//     (bosses, pockets, through cuts and lettering whose walls follow from one loop), relief lines;
//   * prompts pointing at the skill's own scripts (CAD Code workspaces no longer hold tool copies).
// Result: data/datasets/agent30-cadcode-v3 (built-in, read-only).  Run from the repository root:
//   node bench_cli/scripts/make-agent30-v3.mjs
import fs from 'node:fs';
import path from 'node:path';
import {spawnSync} from 'node:child_process';
import {CAD_CODE,DATASETS,MUTABLE_DATASETS,atomicJson,readJson} from '../src/common.mjs';
import {cloneDataset,editCase,resolveDataset} from '../src/datasets.mjs';

const NAME='agent30-cadcode-v3',SOURCE='agent30-cadcode-v2',IR='STEPIR v6.3';
const PY=path.join(CAD_CODE,'.runtime/python/bin/python'),STEPIR=path.join(CAD_CODE,'skills/simplecadapi/scripts/stepir.py');
const built=path.join(DATASETS,NAME);
if(fs.existsSync(built))throw Error('Already built: '+built);
const head=fs.readFileSync(STEPIR,'utf8').split('\n').slice(0,3).join('\n');
if(!head.includes(IR))throw Error(`${STEPIR} is not ${IR}`);

const PROMPT=`Reconstruct the CAD part in input/target.step as an editable SimpleCAD notebook with SimpleCADAPI 2.2.7. Use the simplecadapi skill and follow its STEP reconstruction workflow (references/workflows/step-reconstruction.md). input/target.ir.jsonl is the target's ${IR} description; read it first (its format: references/inspect/stepir.md).

Deliver under out/:
1. out/model.py: the notebook in the skill's notebook format, with id "model". It must rebuild the part through SimpleCADAPI modeling operations and must not read target.step, target.ir.jsonl, copied BREP/mesh, or any other target-derived geometry file at run time.
2. out/report.json: as the workflow specifies (part_id, riou, evaluations, features, assumptions).

Evaluate with the skill's scripts/stepeval.py (the system prompt gives its path): stepeval.py out/model.py input/target.step --out eval/N (a new N for each attempt). "ok": true is the acceptance check; keep the best notebook at out/model.py.
You have 60 minutes, with no fixed model/tool call count. Finish naturally when complete or unable to make further progress. The evaluator will independently replay out/model.py and score the STEP it produces.`;

const tmp=fs.mkdtempSync(path.join(path.dirname(MUTABLE_DATASETS),'agent30-v3-'));
try{
  const ds=cloneDataset(SOURCE,NAME);
  const promptFile=path.join(tmp,'prompt.txt');fs.writeFileSync(promptFile,PROMPT+'\n');
  const solids={};
  for(const entry of ds.manifest.cases){
    const step=path.join(ds.dir,'cases',entry.id,'target.step'),ir=path.join(tmp,entry.id+'.ir.jsonl');
    const r=spawnSync(PY,['-I',STEPIR,step,'--out',ir],{encoding:'utf8',timeout:1800000});
    if(r.status!==0)throw Error(`stepir failed on ${entry.id}: ${(r.stderr||'').slice(-400)}`);
    solids[entry.id]=JSON.parse(fs.readFileSync(ir,'utf8').split('\n')[0]).solids;
    editCase(NAME,entry.id,{ir,promptFile});
    console.log(entry.id,'solids',solids[entry.id]);
  }
  const dir=resolveDataset(NAME).dir,m=readJson(path.join(dir,'manifest.json'));
  m.read_only=true;m.revision=1;delete m.parent;
  m.parent={name:SOURCE,note:`same targets; IR regenerated with ${IR}, prompts point at the skill's own scripts`};
  m.new_run_protocol={...m.new_run_protocol,ir:IR,
    evaluator:"skill scripts/stepeval.py (agent); bench_cli independent notebook replay + strict and robust IoU (score)",
    multi_solid_cases:Object.entries(solids).filter(([,n])=>n!==1).map(([id,n])=>({id,solids:n})),
    note:`Prompt targets the 2.2.7 skill workflow with ${IR}; do not merge with agent30-cadcode-v1/v2 results.`};
  m.created_at=new Date().toISOString();
  atomicJson(path.join(dir,'manifest.json'),m);
  fs.cpSync(path.join(dir,'cases'),path.join(built,'cases'),{recursive:true});
  fs.copyFileSync(path.join(dir,'manifest.json'),path.join(built,'manifest.json'));
  fs.rmSync(dir,{recursive:true,force:true});                // the mutable working copy and its edit revisions
  resolveDataset(NAME);                                      // validates hashes of the built-in copy
  console.log('built',built);
}finally{fs.rmSync(tmp,{recursive:true,force:true});}
